 "content": "from collections import deque


def _components(grid, color):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != color or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for nx, ny in ((x-1, y), (x+1, y), (x, y-1), (x, y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == color and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        q.append((nx, ny))
            result.append(cells)
    return result


def _shape(cells):
    min_r = min(r for r, c in cells)
    min_c = min(c for r, c in cells)
    return frozenset((r-min_r, c-min_c) for r, c in cells)


def transform(grid):
    out = [row[:] for row in grid]
    reference_shapes = {_shape(c) for c in _components(grid, 8)}
    for comp in _components(grid, 1):
        if _shape(comp) in reference_shapes:
            for r, c in comp:
                out[r][c] = 8
    return out
